/** MIT; own original bare U082 retained receiving assemblies,not bus behavior. */
import * as THREE from'three';import{Port,materials}from'../../core/index.js';import{mesh,FACE,portQuaternion}from'../../modeling/parts.js';import{solid,rectangleRing}from'./geometry.js';import{spec}from'./dimensions.js';
export function addConnectors(host,frame){
 const white=materials.plastic(0xe7e8dd,{roughness:.7}),black=materials.plastic(0x171b1a,{roughness:.7}),tin=materials.metal(0xb8b9ae,{roughness:.38}),gold=materials.metal(0xc7a259,{roughness:.42}),box=(parent,s,p,n,m=white)=>mesh(parent,new THREE.BoxGeometry(...s),m,p,'U082 '+n);
 const g=new THREE.Group();g.position.fromArray(spec.grove.position);g.quaternion.copy(portQuaternion('bottom'));g.name='U082 rear white actual4P receiving body';frame.add(g);const grove={frame:g,walls:[],contacts:[],returns:[],tails:[],supports:[]};for(const sign of[-1,1]){grove.walls.push(box(g,[.7,7.5,3.9],[sign*5.05,-3.75,0],'Grove sidewall'));grove.walls.push(box(g,[.65,1.5,.55],[sign*4.1,-2.1,1.675],'Grove actual latch rail'));}grove.floor=box(g,[9.4,7.5,.6],[0,-3.75,-1.65],'Grove actual floor');grove.back=box(g,[9.4,.7,3.3],[0,-7.15,.3],'Grove actual insertion stop');grove.bridge=box(g,[4.5,2.0,.55],[0,-5.2,1.675],'Grove retained roof bridge');for(let i=0;i<4;i++){const x=(i-1.5)*2;grove.contacts.push(box(g,[.42,6.4,.42],[x,-4.4,.4],'Grove retained contact '+(i+1),tin));grove.returns.push(box(g,[.42,.42,2.0],[x,-7.5,1.4],'Grove real bent conductor '+(i+1),tin));grove.tails.push(box(g,[.42,1.4,1.5],[x,-8,2.65],'Grove actual through-PCB tail '+(i+1),tin));}for(const x of[-4.3,4.3])grove.supports.push(box(g,[1.2,2,.6],[x,-6.1,1.75],'Grove physical PCB seat'));grove.port=host.add(new Port({id:'grove',label:'Bare U082 rear HY2.0-4P',connector:'grove',position:spec.grove.position,quaternion:portQuaternion('bottom'),hitSize:[10.8,1,3.9],pinGrid:{cols:4,rows:1,pitch:2,center:[0,.4],order:i=>i+1},pins:spec.grove.pins.map((name,i)=>({n:i+1,name})),meta:{role:'visual-connector',physicalContacts:4,scope:'Documentary J2 numbering only;four-core mechanics,no power/I2C/UART/electrical routing'}}),frame);
 const u=new THREE.Group();u.position.fromArray(spec.usb.position);u.quaternion.copy(FACE.bottom);u.name='U082 front actual USB-C hollow receiver';frame.add(u);const usb={frame:u,contacts:[],returns:[],tails:[],feet:[]};usb.shield=solid(u,rectangleRing(9,3.2,1.6,8.4,2.6,1.3),7.2,[0,0,-7.2],tin,'U082 real hollow USB-C shield');usb.stop=box(u,[8.2,2.4,.55],[0,0,-6.925],'USB-C actual dielectric stop',black);usb.tongue=box(u,[6.7,.65,5.4],[0,0,-4.1],'USB-C retained tongue',black);for(const side of[-1,1])for(let i=0;i<12;i++){const x=(i-5.5)*.5;usb.contacts.push(box(u,[.23,.08,4.3],[x,side*.365,-4.35],'USB-C actual tongue contact',gold));usb.returns.push(box(u,[.16,2.3,.25],[x+side*.08,-.7,-6.5],'USB-C concealed retained conductor',tin));usb.tails.push(box(u,[.16,.12,1.1],[x+side*.08,-1.74,-7.1],'USB-C surface solder tail',tin));}for(const x of[-4.35,4.35])usb.feet.push(box(u,[.9,.3,2.2],[x,-1.65,-5.8],'USB-C real shield PCB retention foot',tin));usb.port=host.add(new Port({id:'usb',label:'Bare U082 USB-C mechanical port',connector:'usb-c',position:spec.usb.position,quaternion:portQuaternion('bottom'),hitSize:[9,1,3.2],meta:{role:'visual-connector',scope:'Physical shield/tongue/contacts only,no USB/UART/power/firmware'}}),frame);
 const b=new THREE.Group();b.position.set(9.7,-10.5,-1.9);b.quaternion.copy(FACE.right);b.name='U082 empty actual2P battery receiver,no battery or cable class';frame.add(b);const battery={frame:b,walls:[],contacts:[],tails:[]};for(const sign of[-1,1])battery.walls.push(box(b,[.5,2.5,3.3],[sign*2,-0,-1.65],'empty battery sidewall'));for(const sign of[-1,1])battery.walls.push(box(b,[3.5,.5,3.3],[0,sign*1,-1.65],'empty battery top/floor'));battery.stop=box(b,[3.5,1.5,.5],[0,0,-3.05],'empty battery actual stop');for(const x of[-.625,.625]){battery.contacts.push(box(b,[.25,.25,2.25],[x,0,-1.9],'empty battery retained contact',gold));battery.tails.push(box(b,[.35,1.3,.3],[x,.7,-2.95],'battery solder retention',tin));}
 return{grove,usb,battery};
}
